package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.admin.*;import jakarta.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class AdminMemberBlocksTest {
 @Autowired EntityManager em;@Autowired AdminMemberBlocks service;
 User user(){var u=User.builder().email(UUID.randomUUID()+"@blocks.test").nickname(UUID.randomUUID().toString().substring(0,12)).provider("LOCAL").status("ACTIVE").build();em.persist(u);return u;}
 void role(String r){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AdminService.Principal(99L,"test",r,"csrf"),null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void outgoingOnlyDeduplicatesReportsAndKeepsRestrictionAfterUnblock(){role("SUPPORT");var a=user();var b=user();var c=user();var v=new MemberVisibility();v.setOwnerId(a.getId());v.setTargetId(b.getId());v.setBlocked(true);em.persist(v);em.persist(UserReport.builder().reporterUserId(a.getId()).reportedUserId(b.getId()).reasonCode("OTHER").detail("test").build());em.persist(UserReport.builder().reporterUserId(c.getId()).reportedUserId(a.getId()).reasonCode("OTHER").detail("test").build());var list=service.list(a.getId(),0);assertEquals(1,list.total());assertEquals(b.getId(),list.items().get(0).id());assertTrue(list.items().get(0).directlyBlocked());assertTrue(list.items().get(0).reported());v.setBlocked(false);assertFalse(service.list(a.getId(),0).items().get(0).directlyBlocked());assertEquals(1,service.list(a.getId(),0).total());assertEquals(0,service.list(a.getId(),1).items().size());}
 @Test void permissionIsEnforcedAtServiceAndRoute(){var a=user();role("REVIEWER");assertThrows(ResponseStatusException.class,()->service.list(a.getId(),0));assertFalse(AdminFilter.allowed("READ_ONLY","GET","/api/admin/console/members/1/blocks"));assertFalse(AdminFilter.allowed("REVIEWER","GET","/api/admin/console/members/1/blocks"));assertTrue(AdminFilter.allowed("SUPPORT","GET","/api/admin/console/members/1/blocks"));}

 @Test void releaseKeepsReportsAndReverseBlocks(){role("SUPPORT");var a=user();var b=user();var forward=new MemberVisibility();forward.setOwnerId(a.getId());forward.setTargetId(b.getId());forward.setBlocked(true);em.persist(forward);var reverse=new MemberVisibility();reverse.setOwnerId(b.getId());reverse.setTargetId(a.getId());reverse.setBlocked(true);em.persist(reverse);var report=UserReport.builder().reporterUserId(a.getId()).reportedUserId(b.getId()).reasonCode("OTHER").detail("preserve evidence").build();em.persist(report);assertThrows(ResponseStatusException.class,()->service.release(a.getId(),b.getId(),new AdminMemberBlocks.Release("")));service.release(a.getId(),b.getId(),new AdminMemberBlocks.Release("회원 민원 확인"));assertFalse(forward.isBlocked());assertTrue(reverse.isBlocked());assertNotNull(report.getContactReleasedAt());assertEquals("OPEN",report.getStatus());assertEquals("preserve evidence",report.getDetail());assertEquals(0,service.list(a.getId(),0).total());assertEquals(1,service.list(b.getId(),0).total());role("REVIEWER");assertThrows(ResponseStatusException.class,()->service.release(b.getId(),a.getId(),new AdminMemberBlocks.Release("test")));}
}
